#include "FreeRTOS.h"#include <string>#include <iostream>#include "task.h"#include "queue.h"#include "Structs.h"#include "timers.h"#include "EEPROM/EEPROM.h"#include "pico/stdlib.h"#include "hardware/timer.h"#include "Task_Control/Control.h"#include "Task_Network/Network.h"#include "Task_UI/UI.h"#include "display/lvgl_port.h"#include "event_groups.h"extern "C" {uint32_t read_runtime_ctr(void) {    return timer_hw->timerawl;}}// lvgl needs timer access so that's a global ptrLVGLPort *g_lvgl_port = nullptr;// timer callbackvoid lvgl_tick_timer_callback(TimerHandle_t xTimer) {    if (g_lvgl_port) {        g_lvgl_port->tick(10);  // 10ms tick    }}int main(){    QueueHandle_t to_control;    QueueHandle_t to_UI;    QueueHandle_t to_network;    QueueHandle_t scan_results_queue;    QueueHandle_t credentials_to_network;    timer_hw->dbgpause = 1;    stdio_init_all();    EventGroupHandle_t event_group = xEventGroupCreate();    TimerHandle_t lvgl_timer = xTimerCreate("LVGL_ticks", pdMS_TO_TICKS(10), pdTRUE, NULL, lvgl_tick_timer_callback);    xTimerStart(lvgl_timer, 0);    to_control = xQueueCreate(10, sizeof(Message));    to_UI = xQueueCreate(10, sizeof(Message));    to_network = xQueueCreate(10, sizeof(Message));    scan_results_queue = xQueueCreate(1, sizeof(Scan_result_msg));    credentials_to_network = xQueueCreate(1, sizeof(Network_credentials));    const TickType_t control_period = pdMS_TO_TICKS(1000);    const TickType_t UI_period = pdMS_TO_TICKS(10);    const TickType_t network_period = pdMS_TO_TICKS(100);    // both control and UI tasks use eeprom    auto i2cbus0 = std::make_shared<PicoI2C>(0, 100000);    auto i2cbus1 = std::make_shared<PicoI2C>(1, 100000);    auto eeprom = std::make_shared<EEPROM>(i2cbus1);    Control control_task(to_UI,to_network,to_control,event_group,control_period, i2cbus0, eeprom);    UI ui_task(to_UI,to_network,to_control,scan_results_queue,credentials_to_network,event_group,UI_period, eeprom);    Network network_task(to_UI,to_network,to_control,scan_results_queue,credentials_to_network,event_group,network_period);    vTaskStartScheduler();    return 0;}